# Python decorator implementation
import threading

def debounce(wait):
    def decorator(fn):
        timer = None
        def debounced(*args, **kwargs):
            nonlocal timer
            if timer:
                timer.cancel()
            timer = threading.Timer(wait, fn, args, kwargs)
            timer.start()
        return debounced
    return decorator

